"Cervical sprain/strain": "\u0420\u0430\u0441\u0442\u044f\u0436\u0435\u043d\u0438\u0435 \u0441\u0432\u044f\u0437\u043e\u043a \u0448\u0435\u0439\u043d\u043e\u0433\u043e \u043e\u0442\u0434\u0435\u043b\u0430",
