"Cervical vertebral fracture": "\u041f\u0435\u0440\u0435\u043b\u043e\u043c \u0448\u0435\u0439\u043d\u043e\u0433\u043e \u043f\u043e\u0437\u0432\u043e\u043d\u043a\u0430",
"Chest": "\u0413\u0440\u0443\u0434\u044c",
"Chest crush": "\u0420\u0430\u0437\u0434\u0430\u0432\u043b\u0435\u043d\u0430 \u0433\u0440\u0443\u0434\u044c",
